// Pull each dataset by node name. The four getAll nodes run in a serial
// chain (Tracker -> Metrics -> Planner -> Job Tasks -> this node), each with
// alwaysOutputData so an empty database still lets the chain continue
// (emitting a single placeholder {} item instead of halting execution).
// dval() normalizes Notion date properties, which can come back either as
// a plain ISO string or as an object like { start, end, time_zone }.
const dval = (v) => (v && typeof v === 'object') ? (v.start ?? null) : (v || null);

// The Notion node's simplified output flattens every property to
// `property_` + lowercase name (spaces -> underscores) and always includes
// a real page `id`. A placeholder {} item from alwaysOutputData has
// neither, so this filters those out without hardcoding a property name.
function hasRow(row) {
  return !!(row && row.id && Object.keys(row).some((k) => k.startsWith('property_')));
}

const trackerRows = $('Get Tracker Rows').all().map((i) => i.json).filter(hasRow);
const metricsRows = $('Get Metrics Rows').all().map((i) => i.json).filter(hasRow);
const plannerRows = $('Get Planner Rows').all().map((i) => i.json).filter(hasRow);
const jobTasksRows = $('Get Job Tasks Rows').all().map((i) => i.json).filter(hasRow);

const today = $now.setZone('Europe/London').startOf('day');
const weekAgo = today.minus({ days: 7 });

// Window = last 7 full days before today (previous Mon-Sun when run on a
// Monday morning).
function inWindow(rawDate) {
  const dateStr = dval(rawDate);
  if (!dateStr) return false;
  const d = DateTime.fromISO(String(dateStr), { zone: 'Europe/London' }).startOf('day');
  if (!d.isValid) return false;
  return d >= weekAgo && d < today;
}

function isOverdue(row) {
  if (row.property_done) return false;
  const dateStr = dval(row.property_date);
  if (!dateStr) return false;
  const d = DateTime.fromISO(String(dateStr), { zone: 'Europe/London' }).startOf('day');
  return d.isValid && d < today;
}

let applicationsSubmitted = 0;
let outreachSent = 0;
let repliesReceived = 0;

for (const row of trackerRows) {
  if (inWindow(row.property_applied_date)) applicationsSubmitted++;
  if (inWindow(row.property_outreach_sent)) outreachSent++;
  if (inWindow(row.property_reply_received)) repliesReceived++;
}

let plannerTasksOverdue = 0;
for (const row of plannerRows) {
  if (isOverdue(row)) plannerTasksOverdue++;
}

let jobTasksOverdue = 0;
for (const row of jobTasksRows) {
  if (isOverdue(row)) jobTasksOverdue++;
}

let classificationVolume = 0;
let notCorrected = 0;
for (const row of metricsRows) {
  if (inWindow(row.property_timestamp)) {
    classificationVolume++;
    if (!row.property_corrected) notCorrected++;
  }
}

const precision = classificationVolume > 0
  ? ((notCorrected / classificationVolume) * 100).toFixed(1)
  : '0.0';

const weekStart = weekAgo.toFormat('d LLL yyyy');
const weekEndDate = today.minus({ days: 1 });

// Formats the digest window as "13–19 Jul 2026", collapsing the month/year
// when both ends fall in the same one and spelling both out otherwise.
function formatWeekRange(start, end) {
  if (start.hasSame(end, 'month') && start.hasSame(end, 'year')) {
    return `${start.toFormat('d')}–${end.toFormat('d LLL yyyy')}`;
  }
  if (start.hasSame(end, 'year')) {
    return `${start.toFormat('d LLL')} – ${end.toFormat('d LLL yyyy')}`;
  }
  return `${start.toFormat('d LLL yyyy')} – ${end.toFormat('d LLL yyyy')}`;
}

const weekRange = formatWeekRange(weekAgo, weekEndDate);
const subject = `Job search digest — week of ${weekRange}`;

const jobOverdueColor = jobTasksOverdue > 0 ? '#b45309' : '#6b7280';
const plannerOverdueColor = plannerTasksOverdue > 0 ? '#b45309' : '#6b7280';

const classifierLine = classificationVolume > 0
  ? `Classifier: ${classificationVolume} emails processed · precision ${precision}%`
  : 'Classifier: no data yet — stats start next week';

// Table-based, inline-styled layout for Outlook/Hotmail webmail compatibility
// (no external CSS/fonts/images, no flexbox/grid).
const html = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#f4f5f7;padding:24px 0;font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
<tr>
<td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;width:100%;background-color:#ffffff;border-radius:8px;padding:24px;">
<tr>
<td style="font-size:22px;font-weight:700;color:#2563eb;padding-bottom:4px;">Job search digest</td>
</tr>
<tr>
<td style="font-size:13px;color:#6b7280;padding-bottom:20px;">${weekRange}</td>
</tr>
<tr>
<td style="padding-bottom:4px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
<tr>
<td align="center" width="33%" style="padding:8px 4px;">
<div style="font-size:28px;line-height:32px;font-weight:700;color:#111827;">${applicationsSubmitted}</div>
<div style="font-size:11px;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-top:4px;">Applications</div>
</td>
<td align="center" width="33%" style="padding:8px 4px;">
<div style="font-size:28px;line-height:32px;font-weight:700;color:#111827;">${outreachSent}</div>
<div style="font-size:11px;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-top:4px;">Outreach</div>
</td>
<td align="center" width="33%" style="padding:8px 4px;">
<div style="font-size:28px;line-height:32px;font-weight:700;color:#111827;">${repliesReceived}</div>
<div style="font-size:11px;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-top:4px;">Replies</div>
</td>
</tr>
</table>
</td>
</tr>
<tr>
<td style="border-top:1px solid #e5e7eb;font-size:0;line-height:0;padding:0;">&nbsp;</td>
</tr>
<tr>
<td style="padding-top:20px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
<tr>
<td colspan="2" style="font-size:12px;font-weight:700;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-bottom:8px;">Needs attention</td>
</tr>
<tr>
<td style="font-size:14px;color:#374151;padding:6px 0;">Job-search tasks overdue</td>
<td align="right" style="font-size:14px;font-weight:700;color:${jobOverdueColor};padding:6px 0;">${jobTasksOverdue}</td>
</tr>
<tr>
<td style="font-size:14px;color:#374151;padding:6px 0;">Planner tasks overdue</td>
<td align="right" style="font-size:14px;font-weight:700;color:${plannerOverdueColor};padding:6px 0;">${plannerTasksOverdue}</td>
</tr>
</table>
</td>
</tr>
<tr>
<td style="border-top:1px solid #e5e7eb;font-size:0;line-height:0;padding:0;">&nbsp;</td>
</tr>
<tr>
<td style="font-size:13px;color:#6b7280;padding-top:20px;">${classifierLine}</td>
</tr>
<tr>
<td style="font-size:12px;color:#9ca3af;padding-top:24px;">Automated by n8n · email-to-task</td>
</tr>
</table>
</td>
</tr>
</table>`;

return [
  {
    json: {
      weekStart,
      subject,
      html,
      applicationsSubmitted,
      outreachSent,
      repliesReceived,
      jobTasksOverdue,
      plannerTasksOverdue,
      classificationVolume,
      precision
    }
  }
];
